function progressionLive(){const s=pack[SETTINGS]||{},rows=xpCurve(s);level=Math.min(Math.max(1,level),rows.length);const r=rows[level-1],prev=rows[99],next=rows[100];const validation=issues();return `<section class="card"><div class="card-head"><div><h2>Live progression</h2><p class="card-label">Actual runtime requirements · log scale</p></div><div class="segmented"><button data-chart="required" class="${chartMode==='required'?'active':''}">Per level</button><button data-chart="total" class="${chartMode==='total'?'active':''}">Total</button></div></div><div class="chart-wrap">${chart(rows)}</div><div class="legend"><span><i></i>Effective XP</span><span><i class="mint"></i>Explicit override</span></div><div class="inspect"><div class="inspect-label"><span>Inspect a target level</span><strong>Level ${level}</strong></div><input type="range" aria-label="Inspect target level" min="1" max="${rows.length}" value="${level}" id="level-slider"><div class="metrics"><div class="metric accent"><span>XP TO REACH LEVEL ${level}</span><strong>${short(r.xp)}</strong><small>${fmt(r.xp)} XP · ${r.source==='override'?'explicit override':'fallback curve'}</small></div><div class="metric"><span>TOTAL XP TO LEVEL ${level}</span><strong>${short(r.total)}</strong><small>${fmt(r.total)} XP</small></div></div></div></section>${prev&&next&&next.xp<prev.xp?card('A real curve discontinuity',notice(`Level 100 requires <strong>${fmt(prev.xp)} XP</strong>; level 101 requires <strong>${fmt(next.xp)} XP</strong>. This is the transition from the explicit table to the fallback curve.`,'warning'),{badge:badge('100 → 101','amber')}):''}${card('Profile check',`<div class="checklist"><div><b>${validation.errors.length?'!':'✓'}</b><span>${validation.errors.length?validation.errors.length+' blocking issue'+(validation.errors.length===1?'':'s'):'Supported values pass validation'}</span></div><div><b>✓</b><span>${safeArray(s.exp_required_per_level).length} explicit XP rows preserved</span></div><div><b>✓</b><span>Effective cap: ${maxLevel(s)} levels</span></div><div><b class="${validation.warnings.length?'warning-icon':''}">${validation.warnings.length?'△':'✓'}</b><span>${validation.warnings.length?validation.warnings.length+' warning'+(validation.warnings.length===1?'':'s')+' to review':'No runtime warnings detected'}</span></div></div><div class="validation-link"><button class="text-button" data-action="validation">Review validation</button></div>`)}${card('What gets exported',`<div class="spec-row"><span>Destination</span><strong>config/ras/</strong></div><div class="spec-row"><span>Mod / Minecraft</span><strong>${h(target)} / ${h(minecraft)}</strong></div><div class="spec-row"><span>Settings authority</span><strong>Server</strong></div><p class="inline-note">XP changes may need a rejoin. Attribute metadata is synced when players join.</p>`)}`}
