function renderLive(){const el=$('#live-preview');if(!el)return;if(view==='progression')el.innerHTML=progressionLive();else if(view==='attributes')el.innerHTML=attributesLive();else if(view==='templates')el.innerHTML=templatesLive();else if(view==='mob')el.innerHTML=mobLive();bindLive()}
function numericValue(el,ref){const value=Number(el.value);if(el.value.trim()===''||!Number.isFinite(value)||!el.checkValidity()){el.classList.add('invalid');invalid.set(ref,'An edited field is empty or outside its valid numeric range.');updateChrome();return null}el.classList.remove('invalid');invalid.delete(ref);return value}
function bindView(){document.querySelectorAll('[data-path][data-key]').forEach(el=>el.addEventListener('input',()=>{const path=el.dataset.path,key=el.dataset.key;if(el.type==='number'){const n=numericValue(el,path+'|'+key);if(n!==null)mutate(path,key,n);else renderLive()}else mutate(path,key,el.type==='checkbox'?el.checked:el.value)}));document.querySelectorAll('[data-lines-path]').forEach(el=>el.addEventListener('input',()=>mutate(el.dataset.linesPath,el.dataset.linesKey,el.value.split('\n'))));document.querySelectorAll('[data-interval]').forEach(el=>el.addEventListener('input',()=>{const index=+el.dataset.interval,n=numericValue(el,SETTINGS+'|interval-'+index+'-'+el.dataset.part);if(n===null){renderLive();return}const rows=pack[SETTINGS].exp_curve_scale_intervals||[],r=intervalEntry(rows[index]);r[el.dataset.part]=n;rows[index]=encodeInterval(r.min,r.max,r.scale);mutate(SETTINGS,'exp_curve_scale_intervals',rows)}));document.querySelectorAll('[data-explicit]').forEach(el=>el.addEventListener('input',()=>{const index=+el.dataset.explicit,n=numericValue(el,SETTINGS+'|override-'+index+'-'+el.dataset.part);if(n===null){renderLive();return}const rows=pack[SETTINGS].exp_required_per_level||[],r=explicitEntry(rows[index]);r[el.dataset.part]=n;rows[index]=encodeExplicit(r.level,r.xp);mutate(SETTINGS,'exp_required_per_level',rows)}));document.querySelectorAll('[data-remove-interval]').forEach(el=>el.addEventListener('click',()=>{pack[SETTINGS].exp_curve_scale_intervals.splice(+el.dataset.removeInterval,1);touched.add(SETTINGS);markPatch(SETTINGS,el.dataset.removeInterval!==undefined?'exp_curve_scale_intervals':'exp_required_per_level');invalid.clear();render()}));document.querySelectorAll('[data-remove-explicit]').forEach(el=>el.addEventListener('click',()=>{pack[SETTINGS].exp_required_per_level.splice(+el.dataset.removeExplicit,1);touched.add(SETTINGS);markPatch(SETTINGS,el.dataset.removeInterval!==undefined?'exp_curve_scale_intervals':'exp_required_per_level');invalid.clear();render()}));document.querySelectorAll('[data-attribute]').forEach(el=>el.addEventListener('click',()=>{attrId=+el.dataset.attribute;render()}));$('#test-points')?.addEventListener('input',e=>{const n=numericValue(e.target,'preview|points');if(n!==null){points=n;renderLive()}});document.querySelectorAll('[data-template]').forEach(el=>el.addEventListener('click',()=>{selectedTemplate=el.dataset.template;render()}));document.querySelectorAll('[data-template-id]').forEach(el=>el.addEventListener('input',()=>{const n=numericValue(el,TEMPLATES+'|'+el.dataset.templateId);if(n!==null){pack[TEMPLATES][selectedTemplate][el.dataset.templateId]=n;touched.add(TEMPLATES);markPatch(TEMPLATES,selectedTemplate);updateChrome();renderLive()}}));document.querySelectorAll('[data-file]').forEach(el=>el.addEventListener('click',()=>{selectedFile=el.dataset.file;render()}));$('#raw-editor')?.addEventListener('input',e=>{const obj=selectedFile==='config/ras/mob_xp.json'&&target==='4.3.0'?draftMob:pack[selectedFile],base=obj?fileText(selectedFile):'';if(e.target.value===base)delete jsonDrafts[selectedFile];else jsonDrafts[selectedFile]=e.target.value;updateChrome()});document.querySelectorAll('[data-add-file]').forEach(el=>el.addEventListener('click',()=>{const p=el.dataset.addFile;if(DEFAULTS[p]){pack[p]=clone(DEFAULTS[p]);freshDefaults.add(p);delete originals[p];delete patches[p];touched.add(p);render()}}));document.querySelectorAll('[data-mob-key]').forEach(el=>el.addEventListener('input',()=>{draftMob[el.dataset.mobKey]=el.checked;mobChanged(el.dataset.mobKey)}));document.querySelectorAll('[data-weight]').forEach(el=>el.addEventListener('input',()=>{const k=el.dataset.weightKey,n=el.type==='checkbox'?el.checked:Number(el.value);if(!isObject(draftMob[el.dataset.weight]))draftMob[el.dataset.weight]={};if(el.type==='checkbox')draftMob[el.dataset.weight][k]=el.checked;else setOptionalNumber(draftMob[el.dataset.weight],k,el.value);el.classList.toggle('invalid',el.type==='number'&&!el.checkValidity());mobChanged(el.dataset.weight)}));document.querySelectorAll('[data-rule]').forEach(el=>el.addEventListener('input',()=>{const r=draftMob.rules[+el.dataset.rule],key=el.dataset.ruleKey;if(el.type==='number')setOptionalNumber(r,key,el.value);else r[key]=el.type==='checkbox'?el.checked:el.value;el.classList.toggle('invalid',el.type==='number'&&el.value!==''&&!el.checkValidity());mobChanged('rules')}));document.querySelectorAll('[data-rule-type]').forEach(el=>el.addEventListener('change',()=>{const r=draftMob.rules[+el.dataset.ruleType],id=r.entity||r.tag;delete r.entity;delete r.tag;r[el.value]=id;draftMobTouched=true;markPatch('config/ras/mob_xp.json','rules');render()}));document.querySelectorAll('[data-remove-rule]').forEach(el=>el.addEventListener('click',()=>{draftMob.rules.splice(+el.dataset.removeRule,1);draftMobTouched=true;markPatch('config/ras/mob_xp.json','rules');render()}));bindLive();bindActions()}
function bindLive(){document.querySelectorAll('[data-chart]').forEach(el=>el.onclick=()=>{chartMode=el.dataset.chart;renderLive()});$('#level-slider')?.addEventListener('change',e=>{level=+e.target.value;renderLive()});document.querySelectorAll('[data-sample]').forEach(el=>el.addEventListener('change',()=>{mobSample[el.dataset.sample]=el.dataset.sample==='tags'?el.value.split(',').map(x=>x.trim()).filter(Boolean):el.type==='number'?Math.max(0,Number(el.value)||0):el.value;renderLive()}));bindActions()}
function bindActions(){document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action))}
function action(name){if(name==='add-interval'){mutate(SETTINGS,'exp_curve_scale_intervals',[...(pack[SETTINGS].exp_curve_scale_intervals||[]),encodeInterval(101,150,1.02)]);render()}if(name==='add-explicit'){const levels=(pack[SETTINGS].exp_required_per_level||[]).map(explicitEntry).filter(Boolean).map(r=>r.level);mutate(SETTINGS,'exp_required_per_level',[...(pack[SETTINGS].exp_required_per_level||[]),encodeExplicit(Math.max(0,...levels)+1,100)]);render()}if(name==='clear-explicit')confirmModal('Clear explicit XP overrides?','The fallback curve will determine all level requirements. Other settings will stay unchanged.',()=>{mutate(SETTINGS,'exp_required_per_level',[]);render()},'Clear overrides');if(name==='validation')validationModal();if(name==='add-rule'){if(!Array.isArray(draftMob.rules))draftMob.rules=[];const ids=new Set(draftMob.rules.map(r=>r.id));let i=draftMob.rules.length+1;while(ids.has('rule-'+i))i++;draftMob.rules.push({id:'rule-'+i,entity:'minecraft:zombie',priority:0,base_xp:40,multiplier:1,apply_difficulty_weighting:true,apply_armor_weighting:true});draftMobTouched=true;markPatch('config/ras/mob_xp.json','rules');render()}if(name==='new-template')newTemplateModal();if(name==='delete-template')confirmModal('Delete '+selectedTemplate+'?','This removes the selected template from the current workspace.',()=>{delete pack[TEMPLATES][selectedTemplate];touched.add(TEMPLATES);markPatch(TEMPLATES,selectedTemplate);selectedTemplate='';render()},'Delete template');if(name==='discard-json'){delete jsonDrafts[selectedFile];render()}if(name==='apply-json'){const el=$('#raw-editor');try{const obj=replaceWorkspaceJson(workspaceState(),selectedFile,el.value);delete jsonDrafts[selectedFile];touched.add(selectedFile);for(const k of invalid.keys())if(k.startsWith(selectedFile+'|'))invalid.delete(k);if(selectedFile==='config/ras/mob_xp.json'){draftMob=clone(obj);draftMobTouched=true;}render();toast('JSON applied. Unknown fields preserved.')}catch(e){$('#json-error').innerHTML=notice(h(e.message),'error')}}}
function modal(content){$('#modal-content').innerHTML=content;$('#modal').showModal();$('#modal-content').querySelector('[data-close]')?.addEventListener('click',()=>$('#modal').close())}
function modalHead(name,sub=''){return `<div class="modal-head"><div><h2>${h(name)}</h2>${sub?`<p>${h(sub)}</p>`:''}</div><button class="close-modal" data-close aria-label="Close dialog">×</button></div>`}
function confirmModal(name,sub,fn,label='Confirm'){modal(modalHead(name,sub)+`<div class="modal-actions"><button class="button secondary" id="cancel">Cancel</button><button class="button primary" id="confirm">${h(label)}</button></div>`);$('#cancel').onclick=()=>$('#modal').close();$('#confirm').onclick=()=>{$('#modal').close();fn()}}
function validationModal(){const v=issues();modal(modalHead('Validation review',`${v.errors.length} blocking issues · ${v.warnings.length} warnings`)+issueList(v)+notice('Validation covers source-verified fields, not every third-party command or custom runtime extension.')+`<div class="modal-actions"><button class="button secondary" id="close-validation">Done</button></div>`);$('#close-validation').onclick=()=>$('#modal').close()}
function newTemplateModal(){modal(modalHead('Create a named build','The new template starts with zero allocated points.')+`<label class="field"><span class="field-label">Template name</span><input id="template-name" placeholder="e.g. warrior" maxlength="64"></label><div id="template-error"></div><div class="modal-actions"><button class="button primary" id="create-template">Create template</button></div>`);$('#create-template').onclick=()=>{const n=$('#template-name').value.trim();if(!/^[a-zA-Z0-9_-]{1,64}$/.test(n)||['enabled','permission-required','__proto__','constructor','prototype'].includes(n)||Object.keys(pack[TEMPLATES]).some(k=>k.toLowerCase()===n.toLowerCase())){$('#template-error').innerHTML=notice('Use a unique name with letters, numbers, underscores or hyphens.','error');return}const p=Object.create(null);for(const {id} of attributeIds())p['attribute_'+id]=0;pack[TEMPLATES][n]=p;touched.add(TEMPLATES);markPatch(TEMPLATES,n);selectedTemplate=n;$('#modal').close();render()}}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
async function importFile(file){if(file.size>LIMITS.maxArchive){toast('File exceeds the 10 MiB limit.');return}try{if(/\.zip$/i.test(file.name)){const {pack:next,originals:raw,extra:extras,freshDefaults:defaults}=await importWorkspaceZip(await file.arrayBuffer()),files={...next,...extras};const apply=()=>{pack=next;originals=raw;extra=extras;freshDefaults=defaults;touched=new Set();draftMobTouched=false;jsonDrafts=Object.create(null);patches=Object.create(null);invalid.clear();workspace=file.name;draftMob=pack['config/ras/mob_xp.json']?clone(pack['config/ras/mob_xp.json']):clone(MOB_DEFAULT);$('#modal').close();render();toast(`Imported ${Object.keys(files).length} files. Originals preserved.`)};modal(modalHead('Import configuration pack',`${Object.keys(next).length} JSON files · ${Object.keys(extras).length} supporting files`)+notice('This replaces the current workspace. Missing files stay absent; defaults are not silently added.')+`<div class="modal-list">${Object.keys(files).map(p=>`<div class="spec-row"><span>${h(p.replace('config/ras/',''))}</span><strong>${scopeOf(p)}</strong></div>`).join('')}</div><div class="modal-actions"><button class="button secondary" id="cancel-import">Cancel</button><button class="button primary" id="apply-import">Replace workspace</button></div>`);$('#cancel-import').onclick=()=>$('#modal').close();$('#apply-import').onclick=apply}else if(/\.json$/i.test(file.name)){const text=await file.text(),obj=parseJson(text),name=file.name;let suggestions=[];if(name==='settings.json')suggestions=['config/ras/settings.json','config/ras/attributes/settings.json','config/ras/display/settings.json'];else if(/^attribute_\d+\.json$/.test(name))suggestions=['config/ras/attributes/'+name,'config/ras/display/'+name];else suggestions=['config/ras/'+name];modal(modalHead('Import one JSON file','Choose its role. The other workspace files stay in place.')+`<label class="field"><span class="field-label">Destination path</span><select id="import-path">${suggestions.map(p=>`<option>${h(p)}</option>`).join('')}</select></label>`+notice('Same-named settings and attribute files exist in different folders. The selected destination will be replaced.')+`<div class="modal-actions"><button class="button secondary" id="cancel-import">Cancel</button><button class="button primary" id="apply-import">Import file</button></div>`);$('#cancel-import').onclick=()=>$('#modal').close();$('#apply-import').onclick=()=>{const p=normalizePath($('#import-path').value);replaceWorkspaceJson(workspaceState(),p,text);delete jsonDrafts[p];touched.delete(p);for(const k of invalid.keys())if(k.startsWith(p+'|'))invalid.delete(k);workspace=workspace==='Fresh defaults'?'Defaults + imported file':workspace;if(p==='config/ras/mob_xp.json'){draftMob=clone(obj);draftMobTouched=false;}$('#modal').close();render();toast('File imported. Original text preserved.')}}else throw Error('Choose a JSON file or ZIP archive.')}catch(e){modal(modalHead('Import stopped')+notice(h(e.message),'error')+`<p class="inline-note">Your existing workspace has not changed. Limits: 10 MiB archive, 1 MiB per file, 150 entries, 64 JSON nesting levels.</p>`)}finally{$('#file-input').value=''}}
function exportBytes(scope){return exportWorkspace(workspaceState(),scope);}
function exportModal(){const v=issues(),paths=allPaths();modal(modalHead('Review config export',`RAS ${target} · Minecraft ${minecraft}`)+`<label class="field"><span class="field-label">Export scope</span><select id="export-scope"><option value="all">Complete workspace · separate folders retained</option><option value="server">Server gameplay files</option><option value="client">Client display files</option></select></label><div class="modal-list">${paths.map(p=>`<div class="spec-row"><span>${h(p.replace('config/ras/',''))}</span><strong>${touched.has(p)?'edited':originals[p]?'original':extra[p]?'preserved':'defaults'} · ${scopeOf(p)}</strong></div>`).join('')}</div>${v.errors.length?notice(`${v.errors.length} blocking issue${v.errors.length===1?'':'s'}. Resolve them before export.`,'error'):`${notice('ZIP keeps config/ras paths. Extract into the game or server directory after backing up existing files. No files on your computer are changed by this tool.')}`}${v.errors.length||v.warnings.length?issueList(v):''}${v.warnings.length?`<label class="toggle-row"><span>I reviewed the ${v.warnings.length} warning${v.warnings.length===1?'':'s'}</span><input id="ack-warnings" type="checkbox"></label>`:''}${target==='4.3.0'?'<div class="notice warning"><span>4.3.0 export includes mob_xp.json. Use only with RAS 4.3.0; this file is not supported by 4.2.6.</span></div>':Object.hasOwn(pack,'config/ras/mob_xp.json')||draftMobTouched||draftMob.rules?.length||draftMob.enabled?'<p class="inline-note">4.3.0 mob reward fields are excluded from this 4.2.6 export.</p>':''}<div class="modal-actions"><button class="button secondary" id="cancel-export">Cancel</button><button class="button primary" id="download-export" ${v.errors.length||v.warnings.length?'disabled':''}>Download config ZIP</button></div>`);$('#cancel-export').onclick=()=>$('#modal').close();$('#ack-warnings')?.addEventListener('change',e=>{$('#download-export').disabled=v.errors.length>0||!e.target.checked});$('#download-export').onclick=()=>{try{const scope=$('#export-scope').value,files=exportBytes(scope);if(!Object.keys(files).length)throw Error('No files in the selected scope.');const bytes=writeZip(files),blob=new Blob([bytes],{type:'application/zip'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`RAS-${target}-MC-${minecraft}-${scope}-config.zip`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);$('#modal').close();toast('Config ZIP downloaded. Back up existing configs before installing.')}catch(e){toast(e.message)}}}
$('#source-link').href=`https://github.com/MeherBenSalem/RPG-Attribute-System/tree/${SOURCE_SHA}`;
$('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b){view=b.dataset.view;render()}});$('.brand').onclick=e=>{e.preventDefault();view='progression';render()};$('#target-version').onchange=e=>{target=e.target.value;render()};$('#minecraft-version').onchange=e=>{minecraft=e.target.value;updateChrome();renderLive()};$('#import-button').onclick=()=>$('#file-input').click();$('#file-input').onchange=e=>{const file=e.target.files[0];if(file)importFile(file)};$('#export-button').onclick=exportModal;$('#reset-button').onclick=()=>confirmModal('Reset to source defaults?','This discards current edits and imports. Download a config ZIP first if you want to keep them.',()=>{({pack,originals,extra,patches,target,draftMob,freshDefaults}=createFreshWorkspace());touched=new Set();invalid.clear();draftMobTouched=false;jsonDrafts=Object.create(null);workspace='Fresh defaults';target='4.2.6';render()},'Reset workspace');window.addEventListener('beforeunload',e=>{if(touched.size||workspace!=='Fresh defaults'||draftMobTouched||draftMob.rules?.length||Object.keys(jsonDrafts).length){e.preventDefault();e.returnValue=''}});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});render();
